import {
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  length,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    TorusKnotGeometry,
    CylinderGeometry,
    PlaneGeometry,
    CircleGeometry,
    DirectionalLight,
    PointLight,
    Color,
    RepeatWrapping,
  } = THREE;

  const group = new Group();
  group.name = 'pedestal-material-study';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const cBottom = new Color(stops[0].hex);
  const cMid = new Color(stops[Math.min(1, stops.length - 1)].hex);
  const cTop = new Color(stops[stops.length - 1].hex);

  // ---------- Backdrop (fills frame, vertical gradient) ----------
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const lower = mix(
      vec3(cBottom.r, cBottom.g, cBottom.b),
      vec3(cMid.r, cMid.g, cMid.b),
      smoothstep(0.0, 0.7, v)
    );
    const grad = mix(
      lower,
      vec3(cTop.r * 1.35, cTop.g * 1.35, cTop.b * 1.4),
      smoothstep(0.62, 1.0, v)
    );
    backdropMat.colorNode = vec4(grad, float(1.0));
    backdropMat.toneMapped = false;
  }
  const backdrop = new Mesh(new PlaneGeometry(11, 8), backdropMat);
  backdrop.position.set(0, 0.6, -3);
  group.add(backdrop);

  // ---------- Cinematic floor ----------
  const floorMat = new MeshStandardNodeMaterial();
  floorMat.roughness = 0.5;
  floorMat.metalness = 0.25;
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const base = vec3(cBottom.r * 1.2, cBottom.g * 1.2, cBottom.b * 1.25);
    const edge = vec3(cBottom.r * 0.4, cBottom.g * 0.4, cBottom.b * 0.45);
    const g = mix(base, edge, smoothstep(0.0, 1.0, d));
    floorMat.colorNode = vec4(g, float(1.0));
  }
  const floor = new Mesh(new PlaneGeometry(16, 12), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, -0.86, -1.0);
  group.add(floor);

  // ---------- Pedestal ----------
  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new Color(colors.surface || '#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedestal = new Mesh(new CylinderGeometry(1.1, 1.12, 0.5, 96, 1, false), pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);

  // chamfered top edge catching key light
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.color = new Color('#20202a');
  chamferMat.roughness = 0.42;
  chamferMat.metalness = 0.5;
  const chamfer = new Mesh(new CylinderGeometry(1.1, 1.15, 0.03, 96, 1, false), chamferMat);
  chamfer.position.set(0, -0.365, 0);
  group.add(chamfer);

  // ---------- Pedestal contact shadow on floor ----------
  const floorShadowMat = new MeshBasicNodeMaterial();
  floorShadowMat.transparent = true;
  floorShadowMat.depthWrite = false;
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const a = smoothstep(1.0, 0.15, d).mul(0.55);
    floorShadowMat.colorNode = vec4(vec3(0.0, 0.0, 0.0), a);
    floorShadowMat.toneMapped = false;
  }
  const floorShadow = new Mesh(new CircleGeometry(1.7, 72), floorShadowMat);
  floorShadow.rotation.x = -Math.PI / 2;
  floorShadow.position.set(0, -0.85, 0);
  group.add(floorShadow);

  // ---------- Knot contact shadow on pedestal top ----------
  const topShadowMat = new MeshBasicNodeMaterial();
  topShadowMat.transparent = true;
  topShadowMat.depthWrite = false;
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.5);
    topShadowMat.colorNode = vec4(vec3(0.0, 0.0, 0.0), a);
    topShadowMat.toneMapped = false;
  }
  const topShadow = new Mesh(new CircleGeometry(0.95, 64), topShadowMat);
  topShadow.rotation.x = -Math.PI / 2;
  topShadow.position.set(0, -0.343, 0);
  group.add(topShadow);

  // ---------- Torus knot (hero, brushed titanium) ----------
  const knotMat = new MeshPhysicalNodeMaterial();
  knotMat.color = new Color('#5c5f66'); // dark titanium albedo -> reads as metal, not plaster
  knotMat.roughness = 0.5;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  knotMat.envMapIntensity = 0.9;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  const knot = new Mesh(new TorusKnotGeometry(0.7, 0.22, 220, 36), knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);

  // brushed-metal roughness map (multiplies base roughness -> highlights break up)
  ctx.textureLoader
    .loadTexture(config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png')
    .then((tex) => {
      tex.wrapS = RepeatWrapping;
      tex.wrapT = RepeatWrapping;
      knotMat.roughnessMap = tex;
      knotMat.normalMap = tex;
      knotMat.normalScale = new THREE.Vector2(0.15, 0.15);
      knotMat.roughness = 0.55;
      knotMat.needsUpdate = true;
    })
    .catch(() => {});

  // ---------- Node-local studio lights (create brushed specular streaks) ----------
  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(3.5, 4.5, 4);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent || '#ff2a38'), 0.9);
  rim.position.set(-4, 2.8, -2.5);
  group.add(rim);

  const topFill = new DirectionalLight(0xdfe4ee, 0.5);
  topFill.position.set(0, 5, 1.5);
  group.add(topFill);

  // point "softboxes" give the metal something to reflect as streaks
  const streakA = new PointLight(0xffffff, 0.55, 12, 2);
  streakA.position.set(2.2, 1.4, 2.6);
  group.add(streakA);

  const streakB = new PointLight(0xbfc4cf, 0.4, 12, 2);
  streakB.position.set(-2.2, 1.0, 2.4);
  group.add(streakB);

  // ---------- Text ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ?? [
      { text: 'Material study 03', role: 'headline' },
      { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption' },
    ];

  const textMeshes = [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const role = item.role || 'caption';
    let mesh;
    if (role === 'headline') {
      mesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: 68,
        color: colors.paper || '#e8ecf2',
        align: 'center',
      });
      mesh.position.set(0, -1.2, 0.2);
    } else {
      mesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: 18,
        color: colors.paper || '#e8ecf2',
        align: 'center',
        letterSpacingPx: 2,
      });
      mesh.position.set(0, -1.62, 0.2);
    }
    group.add(mesh);
    textMeshes.push(mesh);
  }

  // ---------- Entrance motion ----------
  const tls = [];
  knot.scale.setScalar(1.04);
  tls.push(
    gsap.to(knot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' })
  );

  for (let i = 0; i < textMeshes.length; i++) {
    const m = textMeshes[i];
    const baseY = m.position.y;
    m.position.y = baseY + 0.3;
    tls.push(
      gsap.to(m.position, {
        y: baseY,
        duration: 0.7,
        delay: 0.1 + i * 0.08,
        ease: 'power3.out',
      })
    );
  }

  // ---------- Cinematic primitives ----------
  const primResults = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'orbit' ? knot : group;
      const r = fn(target, p.params || {});
      if (r) primResults.push(r);
    }
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const t of tls) t.kill?.();
    for (const r of primResults) r.cleanup?.();
    group.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        const m = obj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose?.());
        else m?.dispose?.();
      }
    });
    if (knotMat.roughnessMap) knotMat.roughnessMap.dispose?.();
  };

  return group;
}
